/* Loads the approved oriental theme, then the original offline JSZip build. */
(() => {
  const theme = document.createElement("link");
  theme.rel = "stylesheet";
  theme.href = "./theme-oriental.css?v=2026-08-05";
  document.head.appendChild(theme);

  document.write('<script src="vendor/jszip-core.min.js"><\/script>');
})();
